package com.bplus.share;
import android.app.*;import org.json.*;import java.util.*;import java.net.*;import java.io.*;
public final class RecallAction{
 public static void show(Activity a,String thread,ArrayList<JSONObject> selected,Runnable refresh){if(thread.startsWith("live_")){new AppDialog(a).setMessage(R.string.recall_private_only).setPositiveButton(android.R.string.ok,null).show();return;}for(JSONObject m:selected)if(!m.optBoolean("me")||!Recall.valid(m.optString("wireId"))||!Recall.valid(m.optString("recallKey"))){new AppDialog(a).setTitle(R.string.delete_everyone).setMessage(R.string.recall_unavailable).setPositiveButton(android.R.string.ok,null).show();return;}new AppDialog(a).setTitle(R.string.delete_everyone).setMessage(R.string.recall_confirm).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.action_delete,(d,n)->{new Thread(()->{int ok=0;Set<String> removed=new HashSet<>();for(JSONObject m:selected){JSONObject peer=Store.peerById(thread);boolean deleted=false;try{JSONObject b=new JSONObject().put("from",Store.get("deviceId","")).put("token",Store.token()).put("id",m.getString("wireId")).put("key",m.getString("recallKey"));JSONObject result=call(peer,b);deleted=result.optString("status").equals("deleted");}catch(Exception ignored){}if(deleted){ok++;removed.add(ChatRules.key(m));}else{synchronized(Store.class){JSONArray t=Store.thread(thread);for(int i=0;i<t.length();i++){JSONObject f=t.optJSONObject(i);if(f!=null&&ChatRules.key(f).equals(ChatRules.key(m)))try{f.put("recallFailed",true);}catch(Exception ignored){}}Store.saveThread(thread,t);}}}synchronized(Store.class){Store.saveThread(thread,ChatRules.removeMessages(Store.thread(thread),removed));}final int success=ok;a.runOnUiThread(()->{refresh.run();new AppDialog(a).setTitle(R.string.delete_everyone).setMessage(a.getString(R.string.recall_result,success,selected.size()-success)).setPositiveButton(android.R.string.ok,null).show();});}).start();}).show();}
 static JSONObject call(JSONObject peer,JSONObject b)throws Exception{if(peer==null)throw new IOException();HttpURLConnection c=(HttpURLConnection)new URL("http://"+peer.getString("ip")+":"+peer.optInt("port",Store.PORT)+"/recall").openConnection();c.setConnectTimeout(5000);c.setReadTimeout(8000);c.setRequestMethod("POST");c.setDoOutput(true);byte[] body=b.toString().getBytes("UTF-8");c.setFixedLengthStreamingMode(body.length);try{try(OutputStream out=c.getOutputStream()){out.write(body);}if(c.getResponseCode()!=200)throw new IOException();ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] chunk=new byte[256];int n;while((n=in.read(chunk))>0){bytes.write(chunk,0,n);if(bytes.size()>4096)throw new IOException();}}return new JSONObject(bytes.toString("UTF-8"));}finally{c.disconnect();}}
}
